  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Loop over K
  int K_TILE_MAX = size<3>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(tiled_copy_a, tAgA(_,_,_,k_tile), tAsA);
    copy(tiled_copy_b, tBgB(_,_,_,k_tile), tBsB);
    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();
    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Epilogue
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

// Specialized kernel for GEMM where N and K are small relative to M.
// This matches a tall-and-skinny problem shape (M >> N, K): we tile only
// over the large M dimension (one CTA covers a chunk of rows, one thread
// per row) and keep the small N,K dimensions entirely inside the CTA:
// B (the small K x N operand) is staged once into shared memory per CTA
// and reused by every thread/row in that CTA, while the K-reduction and
// N-outputs are kept in registers and unrolled.
template <int MAX_N>
__global__ void gemm_tallskinny_kernel(const float* __restrict__ A,
                                        const float* __restrict__ B,
                                        float* __restrict__ C,
                                        int M, int N, int K) {
  extern __shared__ float sB[]; // K*N floats, row-major (k*N + n)
  int tid = threadIdx.x;
  int nthreads = blockDim.x;
  int KN = K * N;
  for (int idx = tid; idx < KN; idx += nthreads) {
    sB[idx] = B[idx];
  }
  __syncthreads();
  int row = blockIdx.x * blockDim.x + tid;
  if (row < M) {
    float acc[MAX_N];
    #pragma unroll
    for (int n = 0; n < MAX_N; ++n) {
      if (n < N) acc[n] = 0.0f;
    }
    const float* Arow = A + (size_t)row * K;
    for (int k = 0; k < K; ++k) {
      float a = Arow[k];
      const float* sBk = sB + k * N;
      #pragma unroll
      for (int n = 0; n < MAX_N; ++n) {
        if (n < N) acc[n] += a * sBk[n];
      }
    }
    float* Crow = C + (size_t)row * N;
    #pragma unroll
    for (int n = 0; n < MAX_N; ++n) {
      if (n < N) Crow[n] = acc[n];
    }
  }
}
template <int MAX_N>
static void launch_tallskinny(const float* ptrA, const float* ptrB, float* ptrC,
                               int M, int N, int K, cudaStream_t stream) {
  int threads = 256;
  int blocks = (M + threads - 1) / threads;
  size_t smem = (size_t)K * N * sizeof(float);
  gemm_tallskinny_kernel<MAX_N><<<blocks, threads, smem, stream>>>(ptrA, ptrB, ptrC, M, N, K);
}
template<int BLOCK_M, int BLOCK_N, int TM, int TN>
__global__ void gemm_smallk_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int M, int N, int K) {
  // Specialized kernel for GEMMs where K is small relative to M and N
  // (e.g. M and N both large, K only a few tens of elements). Instead of
  // the generic square 128x128x32 CTA tiling (which tiles/loops over K),
  // here we tile over the two large output dimensions M and N and keep
  // the entire small K dimension resident in shared memory / registers
  // for the whole CTA, fully unrolling the K-reduction with no K-loop
  // across tiles.
  extern __shared__ float smem[];
  float* sA = smem;                 // BLOCK_M * K, row-major
  float* sB = smem + BLOCK_M * K;   // K * BLOCK_N, row-major
  const int block_row = blockIdx.y * BLOCK_M;
  const int block_col = blockIdx.x * BLOCK_N;
  const int nthreads = blockDim.x;
  const int THREADS_N = BLOCK_N / TN;
  const int tx = threadIdx.x % THREADS_N;
  const int ty = threadIdx.x / THREADS_N;
  const int totalA = BLOCK_M * K;
  for (int idx = threadIdx.x; idx < totalA; idx += nthreads) {
    int r = idx / K;
    int c = idx % K;
    int gr = block_row + r;
    sA[idx] = (gr < M) ? A[(size_t)gr * K + c] : 0.0f;
  }
  const int totalB = K * BLOCK_N;
  for (int idx = threadIdx.x; idx < totalB; idx += nthreads) {
    int r = idx / BLOCK_N;
    int c = idx % BLOCK_N;
    int gc = block_col + c;
    sB[idx] = (gc < N) ? B[(size_t)r * N + gc] : 0.0f;
  }
  __syncthreads();
  float acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    #pragma unroll
    for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;
  }
  for (int k = 0; k < K; ++k) {
    float a_reg[TM];
    #pragma unroll
    for (int i = 0; i < TM; ++i) a_reg[i] = sA[(ty * TM + i) * K + k];
    float b_reg[TN];
    #pragma unroll
    for (int j = 0; j < TN; ++j) b_reg[j] = sB[k * BLOCK_N + tx * TN + j];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
      #pragma unroll
      for (int j = 0; j < TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
    }
  }
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    int gr = block_row + ty * TM + i;
    if (gr < M) {
      #pragma unroll
      for (int j = 0; j < TN; ++j) {
        int gc = block_col + tx * TN + j;
        if (gc < N) C[(size_t)gr * N + gc] = acc[i][j];
      }
    }
  }
}
// Host wrapper: computes C = A @ B for A:[M,K], B:[K,N] row-major float32 tensors.
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions of A and B must match");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto Cmat = torch::empty({M, N}, A.options());
  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = Cmat.data_ptr<float>();
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // Specialized path: keep the (small) N,K dimensions entirely inside the
  // CTA (staged in shared memory / unrolled registers) and tile only over
  // the large M dimension. This matches the tall-and-skinny shape of this
  // problem (M >> N, K) far better than the generic 128x128x32 CTA tiling
  // used for square-ish GEMMs below.
  size_t smem_bytes = (size_t)K * N * sizeof(float);
  bool used_tallskinny = false;
  if (M > 0 && N > 0 && K > 0 && N <= 128 && smem_bytes <= 48 * 1024) {
    if (N <= 16) {
      launch_tallskinny<16>(ptrA, ptrB, ptrC, M, N, K, stream);
    } else if (N <= 32) {
      launch_tallskinny<32>(ptrA, ptrB, ptrC, M, N, K, stream);
    } else if (N <= 64) {
      launch_tallskinny<64>(ptrA, ptrB, ptrC, M, N, K, stream);
    } else {
      launch_tallskinny<128>(ptrA, ptrB, ptrC, M, N, K, stream);
    }
    used_tallskinny = true;
  }
  if (used_tallskinny) {
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUTE tall-skinny gemm launch failed: ", cudaGetErrorString(err));
    return Cmat;
  }
  // Specialized path: when K is small relative to M and N (e.g. a rank-K
  // update shape with large M and N), tile over the two large output
  // dimensions and keep the entire K dimension staged in shared memory
  // per CTA, fully unrolling the K-reduction (no K-loop across tiles).
  // This matches the actual problem shape here far better than the
  // generic square 128x128x32 CTA tiling used below, and better than the
  // tall-skinny path above (which only specializes for small N).
  if (M > 0 && N > 0 && K > 0 && K <= 64) {
    constexpr int BLOCK_M = 64;
    constexpr int BLOCK_N = 64;
    constexpr int TM = 4;
    constexpr int TN = 4;
    dim3 block_sk((BLOCK_M / TM) * (BLOCK_N / TN));
    dim3 grid_sk((N + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M);
    size_t smem_sk = (size_t)(BLOCK_M * K + K * BLOCK_N) * sizeof(float);
    gemm_smallk_kernel<BLOCK_M, BLOCK_N, TM, TN><<<grid_sk, block_sk, smem_sk, stream>>>(ptrA, ptrB, ptrC, M, N, K);
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUTE small-K gemm launch failed: ", cudaGetErrorString(err));
    return Cmat;
  }
  // Fallback for shapes that don't tile evenly with our fixed 128x128x8 tiling,
  // or where N,K are too large to use the tall-skinny specialization.
  if (M % 128 != 0 || N % 128 != 0 || K % 8 != 0) {
    return torch::matmul(A_c, B_c);
  }
  // A is row-major (M,K): stride (K,1)
  auto dA = make_stride(K, Int<1>{});
  // B is row-major (K,N); we present it as an (N,K) tensor (transposed view): stride (1,N)
  auto dB = make_stride(Int<1>{}, N);
  // C is row-major (M,N): stride (N,1)
  auto dC = make_stride(N, Int<1>{});
  auto shape_MNK = make_shape(M, N, K);
  dim3 dimBlock(256);
  dim3 dimGrid((M + 127) / 128, (N + 127) / 128);
  gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));
  return Cmat;
}
